create or replace function app.academy_questions_joke() returns trigger
language plpgsql security definer set search_path = public, app, pg_temp as $$
declare
  v_bank text[] := app.academy_joke_bank();
  v_n integer := cardinality(v_bank);
  v_len integer;
  v_used text[];
  v_i integer;
  v_try integer := 0;
  v_pos integer;
begin
  if jsonb_typeof(new.options) <> 'array' then return new; end if;
  v_len := jsonb_array_length(new.options);
  -- one already there (a question saved again with its joke): leave it; seven options is the most a question holds
  if v_len >= 7 or exists (select 1 from jsonb_array_elements_text(new.options) o where o = any (v_bank)) then return new; end if;
  -- the joke: from the question's words, and one a sibling question of the section does not already use
  select coalesce(array_agg(o), '{}') into v_used
    from academy_questions q, jsonb_array_elements_text(q.options) o
   where q.section_id = new.section_id and q.id <> new.id and o = any (v_bank);
  v_i := (abs(hashtextextended(new.prompt, 0)) % v_n)::integer;
  while v_try < v_n and v_bank[v_i + 1] = any (v_used) loop
    v_i := (v_i + 1) % v_n; v_try := v_try + 1;
  end loop;
  -- its place among the options: anywhere, the first and the last included
  v_pos := (abs(hashtextextended(new.prompt, 7)) % (v_len + 1))::integer;
  new.options := (select jsonb_agg(t.x order by t.k) from (
      select k, new.options -> k as x from generate_series(0, v_pos - 1) k
      union all select v_pos, to_jsonb(v_bank[v_i + 1])
      union all select k + 1, new.options -> k from generate_series(v_pos, v_len - 1) k) t);
  if v_pos <= new.answer then new.answer := new.answer + 1; end if;
  return new;
end $$;
comment on function app.academy_questions_joke() is '4200: every question carries one funny wrong option; added at a pseudo-random place, the right answer keeps pointing at the same option.';

drop trigger if exists academy_questions_a_joke on academy_questions;
create trigger academy_questions_a_joke before insert or update of options, answer on academy_questions
  for each row execute function app.academy_questions_joke();

-- every question there is gets its joke now (the trigger does it; the options column is named so it fires)
update academy_questions set options = options;

-- ================================================================ 2. the "See it" lesson of every section
-- the scene check (an Admin saving a lesson) knows the new picture kinds and wants their alt text
create or replace function app.academy_check_scenes(p jsonb) returns void
language plpgsql immutable set search_path = public, app, pg_temp as $$
declare s jsonb; k text;
begin
  if jsonb_typeof(p) <> 'array' or jsonb_array_length(p) = 0 then raise exception 'A lesson needs at least one scene' using errcode = '22023'; end if;
  for s in select * from jsonb_array_elements(p) loop
    if jsonb_typeof(s) <> 'object' or length(btrim(coalesce(s ->> 'caption', ''))) = 0 then raise exception 'Each scene needs a caption' using errcode = '22023'; end if;
    k := coalesce(s #>> '{visual,kind}', '');
    if k not in ('title', 'chat', 'list', 'steps', 'money', 'rule', 'shot', 'pic', 'compare', 'flow', 'dodont', 'icons') then
      raise exception 'Each scene needs a picture: title, chat, list, steps, money, rule or shot (a guide screenshot), or pic, compare, flow, dodont or icons' using errcode = '22023';
    end if;
    if k in ('pic', 'compare', 'flow', 'dodont', 'icons') and length(btrim(coalesce(s #>> '{visual,alt}', ''))) < 3 then
      raise exception 'A picture scene needs its alt text' using errcode = '22023';
    end if;
  end loop;
end $$;
comment on column academy_lessons.scenes is 'Scenes in order: caption (on screen), say (the narration; the caption when empty) and visual (kind: title, chat, list, steps, money, rule, shot: a guide screenshot; or, 4200, pic: a screen with pins, compare: good and bad photos, flow: a diagram, dodont: Do and Do not pairs, icons: key steps with icons; the picture kinds carry alt text).';

